**Additions to pose-math.ts:**

```ts
/**
 * TASK-78: rigid chase pose — the camera is fixed at the chase offset relative
 * to the ship's current position, rotated by the view quaternion (a lagged
 * copy of the ship's quat held by the rig). Unlike `chasePose`, which derives
 * the pose from the ship's quat, this takes an independent `viewQuat`, so the
 * rig can smooth orientation (slerp) without ever lerping the position: the
 * camera→ship distance stays sqrt(CHASE_HEIGHT² + CHASE_BEHIND²) at any
 * speed, no v/k lag.
 */
export interface RigidChasePose {
  position: Vec3;
  look: Vec3;
  /** The ship's up rotated by the view quat (the camera rolls with the ship). */
  up: Vec3;
}

export function rigidChasePose(shipPos: Vec3, viewQuat: Quat): RigidChasePose {
  const offset: Vec3 = { x: 0, y: CHASE_HEIGHT, z: -CHASE_BEHIND };
  const ahead: Vec3 = { x: 0, y: 0, z: CHASE_LOOK_AHEAD };
  return {
    position: vecAdd(shipPos, quatRotateVector(viewQuat, offset)),
    look: vecAdd(shipPos, quatRotateVector(viewQuat, ahead)),
    up: quatRotateVector(viewQuat, { x: 0, y: 1, z: 0 }),
  };
}
```

